with cleaned as (select *, case when promo_code in ('SPRING10', 'VIP') then 'Tier 1' else 'Other' end as promo_code_group, coalesce(channel, 'DIRECT') as channel_clean from promotions where ends_on >= date '2023-11-18') select channel, count(case when channel = 'store' then 1 end) as store_count, round(avg(discount_pct), 2) as avg_discount_pct, count(case when channel = 'web' then 1 end) as web_count, sort_array(collect_set(promo_code)) as promo_code_list, round(sum(discount_pct) / nullif(count(case when channel = 'web' then 1 end), 0), 2) as discount_pct_per_web from cleaned group by channel having count(case when channel = 'web' then 1 end) < 1000
